"""Portable numerical references generated by the original MATLAB smooth.m."""

import importlib
import json
from pathlib import Path
import sys

import numpy as np
import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
smooth = importlib.import_module("ctfire_py.fire_2d_angle").smooth
REFERENCE = Path(__file__).parent / "test_results/smoothing_test_files/matlab_smoothing.json"
REFERENCES = json.loads(REFERENCE.read_text())
CASES = REFERENCES["cases"]


@pytest.mark.parametrize("case", CASES, ids=[case["name"] for case in CASES])
def test_smooth_matches_matlab_reference(case):
    image = np.array(case["input"], dtype=case["dtype"]).reshape(case["shape"])
    original = image.copy()
    expected = np.array(case["expected"], dtype=case["dtype"]).reshape(case["shape"])
    actual = smooth(image, case["sigma"])
    assert actual.dtype == expected.dtype
    np.testing.assert_array_equal(image, original)
    if image.dtype == np.float32:
        # MATLAB's optimized accumulation order depends on shape/kernel size.
        # General fixtures bound the remaining last-bit differences separately
        # from the strict captured FIRE configuration below.
        np.testing.assert_array_max_ulp(actual, expected, maxulp=2)
        if image.ndim == 3 and image.shape[0] == 1 and image.shape[1] > 1 and case["sigma"] == 0.3:
            # LMP ties in the captured configuration are sensitive to one ULP.
            np.testing.assert_array_equal(actual, expected)
    else:
        # Preserve the existing double/SciPy path; cross-library double
        # accumulation can differ at the last few bits.
        epsilon = 4 * np.finfo(np.float64).eps
        np.testing.assert_allclose(actual, expected, rtol=epsilon, atol=epsilon)


def test_integer_image_smoothing_still_promotes_to_double():
    image = np.arange(12, dtype=np.uint8).reshape(3, 4)
    actual = smooth(image, 0.3)
    assert actual.dtype == np.float64
    np.testing.assert_array_equal(actual, smooth(image.astype(np.float64), 0.3))


@pytest.mark.parametrize("case", REFERENCES["lmp_tie_cases"], ids=lambda case: case["name"])
def test_smoothing_preserves_matlab_lmp_preference(case):
    # Patches include the one-pixel filter support around both candidates.
    # These three score differences caused the final real1 path mismatches;
    # double filtering incorrectly rounded each pair into a tie.
    image = np.array(case["input"], dtype=np.float32).reshape(case["shape"])
    result = smooth(image, case["sigma"])[0]
    scores = np.array([result[row, col] for row, col in case["candidate_row_col"]])
    np.testing.assert_array_equal(scores, np.array(case["expected_values"], dtype=np.float32))
    assert scores[0] > scores[1]
